def deplacer_documents(apps, schema_editor):
    """Range les CV et lettres déjà reçus dans DOCUMENTS_PRIVES_ROOT (même nom relatif, rien à changer en base)."""
    Candidature = apps.get_model('carrieres', 'Candidature')
    for cv, lettre in Candidature.objects.values_list('cv', 'lettre_motivation'):
        for nom in (cv, lettre):
            if not nom:
                continue
            source = os.path.join(settings.MEDIA_ROOT, nom)
            cible = os.path.join(settings.DOCUMENTS_PRIVES_ROOT, nom)
            if os.path.isfile(source) and not os.path.exists(cible):
                os.makedirs(os.path.dirname(cible), exist_ok=True)
                shutil.move(source, cible)


